const message=el('div','toast');const actions=el('div','actions');const cancel=el('button','secondary','取消任务');cancel.disabled=!['queued','dispatching','submitted','running','blocked','uncertain','cancel_requested'].includes(run.status);cancel.onclick=()=>act('cancel',{},message);actions.append(cancel);body.append(actions);
