async function loadEvents(){if(!selected||!$('events'))return;const id=selected;try{let page;do{page=await api('/v1/runs/'+id+'/events?after='+eventCursor);if(selected!==id)return;const known=new Map(eventRows.map(event=>[event.id,event]));for(const event of page.events){known.set(event.id,event);eventCursor=Math.max(eventCursor,event.id);}eventRows=[...known.values()].sort((a,b)=>a.id-b.id).slice(-100);}while(page.events.length===100);if($('events'))$('events').replaceChildren(...eventRows.map(event=>el('div','event',new Date(event.createdAt).toLocaleTimeString()+' · '+(event.type==='provider'?event.data.text:event.type==='state'?(labels[event.data.status]||event.data.status):JSON.stringify(event.data)))));}catch{}}
